/* ============================================================
   Sydney Hot Water Systems - site-wide script for Base44
   Paste this into Base44's custom code / scripts slot (site
   footer). The HTML importer strips <script> from imported
   pages, so every behaviour that cannot be done in CSS lives
   here. Base44 re-renders imported markup after load, so every
   listener below is delegated at document level rather than
   bound to an element at load time.
   ============================================================ */
(function () {
  if (window.__shwsGlobal) { return; }
  window.__shwsGlobal = true;

  var doc = document;
  var CART_KEY = "shws_cart_v1";
  var cartItems = [];

  /* ---------- small helpers ---------- */
  function q(sel, root) { return (root || doc).querySelector(sel); }
  function qa(sel, root) { return Array.prototype.slice.call((root || doc).querySelectorAll(sel)); }
  function toggleBox(name) { return q('input.shws-state[id="shws-' + name + '"]'); }

  function setDrawer(name, open) {
    var box = toggleBox(name);
    if (box) { box.checked = !!open; }
    // mirror onto the class names the original build used, so either hook works
    var el = q(name === "cart" ? "#global-cart" : name === "quote" ? "#global-quick-quote" : ".mobile-panel");
    if (el) { el.classList.toggle("open", !!open); }
    var back = q(name === "cart" ? ".q-backdrop-cart" : ".q-backdrop-quote");
    if (back) { back.classList.toggle("open", !!open); }
    if (name === "cart" && open) { renderCart(); }
  }

  function syncDrawers() {
    ["quote", "cart", "menu"].forEach(function (name) {
      var box = toggleBox(name);
      if (!box) { return; }
      var el = q(name === "cart" ? "#global-cart" : name === "quote" ? "#global-quick-quote" : ".mobile-panel");
      if (el) { el.classList.toggle("open", box.checked); }
      var back = q(name === "cart" ? ".q-backdrop-cart" : ".q-backdrop-quote");
      if (back) { back.classList.toggle("open", box.checked); }
    });
    if (toggleBox("cart") && toggleBox("cart").checked) { renderCart(); }
  }

  function closeAllDrawers() {
    setDrawer("quote", false);
    setDrawer("cart", false);
    setDrawer("menu", false);
  }

  function money(n) {
    try {
      return new Intl.NumberFormat("en-AU", { style: "currency", currency: "AUD" }).format(n);
    } catch (e) {
      return "$" + (Math.round(n * 100) / 100).toFixed(2);
    }
  }

  /* ---------- cart state ---------- */
  function cartLoad() {
    try {
      var raw = window.localStorage.getItem(CART_KEY);
      cartItems = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(cartItems)) { cartItems = []; }
    } catch (e) { cartItems = []; }
  }

  function cartSave() {
    try { window.localStorage.setItem(CART_KEY, JSON.stringify(cartItems)); } catch (e) {}
  }

  function cartTotals() {
    var count = 0, subtotal = 0;
    cartItems.forEach(function (i) {
      count += i.qty;
      subtotal += i.qty * i.price;
    });
    return { count: count, subtotal: subtotal };
  }

  function renderCart() {
    var t = cartTotals();

    qa("[data-cart-count]").forEach(function (el) {
      el.textContent = String(t.count);
      if (t.count > 0) { el.removeAttribute("hidden"); } else { el.setAttribute("hidden", ""); }
    });
    qa("[data-cart-subtotal]").forEach(function (el) { el.textContent = money(t.subtotal); });

    var list = q("[data-cart-list]");
    var empty = q("[data-cart-empty]");
    var foot = q("[data-cart-foot]");
    if (!list) { return; }

    if (!cartItems.length) {
      list.setAttribute("hidden", "");
      list.innerHTML = "";
      if (empty) { empty.removeAttribute("hidden"); }
      if (foot) { foot.setAttribute("hidden", ""); }
      return;
    }

    if (empty) { empty.setAttribute("hidden", ""); }
    if (foot) { foot.removeAttribute("hidden"); }
    list.removeAttribute("hidden");

    list.innerHTML = cartItems.map(function (i) {
      var thumb = i.image
        ? '<img src="' + i.image + '" alt="" loading="lazy">'
        : '<svg aria-hidden="true"><use href="#i-cart"></use></svg>';
      var name = i.url
        ? '<a href="' + i.url + '">' + escapeHtml(i.name) + "</a>"
        : escapeHtml(i.name);
      return (
        '<li data-cart-line="' + escapeHtml(i.id) + '">' +
          '<span class="cart-thumb">' + thumb + "</span>" +
          '<div class="cart-info">' +
            "<h4>" + name + "</h4>" +
            (i.variant ? '<p class="cart-meta">' + escapeHtml(i.variant) + "</p>" : "") +
            '<span class="cart-qty">' +
              '<button type="button" data-cart-dec aria-label="Reduce quantity">&minus;</button>' +
              "<span>" + i.qty + "</span>" +
              '<button type="button" data-cart-inc aria-label="Increase quantity">+</button>' +
            "</span>" +
          "</div>" +
          '<div class="cart-right">' +
            '<span class="cart-price">' + money(i.qty * i.price) + "</span>" +
            '<button type="button" class="cart-del" data-cart-remove aria-label="Remove ' + escapeHtml(i.name) + '">' +
              '<svg aria-hidden="true"><use href="#i-trash"></use></svg>' +
            "</button>" +
          "</div>" +
        "</li>"
      );
    }).join("");
  }

  function escapeHtml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function cartChanged() {
    cartSave();
    renderCart();
    doc.dispatchEvent(new CustomEvent("shws:cartchange", { detail: cartTotals() }));
  }

  function cartAdd(item) {
    var found = null;
    cartItems.forEach(function (i) { if (i.id === item.id) { found = i; } });
    if (found) { found.qty += item.qty || 1; }
    else { cartItems.push({ id: item.id, name: item.name, price: Number(item.price) || 0, qty: item.qty || 1, url: item.url || "", variant: item.variant || "", image: item.image || "" }); }
    cartChanged();
  }

  window.SHWS_CART = {
    add: cartAdd,
    remove: function (id) { cartItems = cartItems.filter(function (i) { return i.id !== id; }); cartChanged(); },
    setQty: function (id, n) {
      cartItems.forEach(function (i) { if (i.id === id) { i.qty = Math.max(1, n); } });
      cartChanged();
    },
    clear: function () { cartItems = []; cartChanged(); },
    get: function () { var t = cartTotals(); return { items: cartItems.slice(), count: t.count, subtotal: t.subtotal }; },
    open: function () { setDrawer("cart", true); },
    close: function () { setDrawer("cart", false); }
  };

  /* ---------- one delegated click handler for the whole site ---------- */
  doc.addEventListener("click", function (ev) {
    var t = ev.target;
    if (!t || !t.closest) { return; }

    // drawers and menu.
    // A <label> already flips its checkbox, so for those we only sync the
    // mirror classes on the next tick and never force a state, otherwise a
    // second click on the same control could not close the drawer.
    var opener = t.closest("[data-quote-open]");
    if (opener) {
      if (opener.tagName === "LABEL") {
        setTimeout(function () { syncDrawers(); prefillService(opener.getAttribute("data-service")); }, 0);
      } else {
        ev.preventDefault();
        setDrawer("cart", false);
        setDrawer("quote", true);
        prefillService(opener.getAttribute("data-service"));
      }
      return;
    }
    var carter = t.closest("[data-cart-open]");
    if (carter) {
      if (carter.tagName === "LABEL") { setTimeout(syncDrawers, 0); }
      else { ev.preventDefault(); setDrawer("quote", false); setDrawer("cart", true); }
      return;
    }
    if (t.closest("[data-quote-close]") || t.closest("[data-quote-backdrop]")) {
      if (t.closest("label")) { setTimeout(syncDrawers, 0); } else { setDrawer("quote", false); }
      return;
    }
    if (t.closest("[data-cart-close]") || t.closest("[data-cart-backdrop]")) {
      if (t.closest("label")) { setTimeout(syncDrawers, 0); } else { setDrawer("cart", false); }
      return;
    }
    if (t.closest("[data-menu-toggle]")) {
      if (t.closest("[data-menu-toggle]").tagName === "LABEL") { return; }
      var box = toggleBox("menu");
      setDrawer("menu", box ? !box.checked : true);
      return;
    }

    // cart line controls
    var line = t.closest("[data-cart-line]");
    if (line) {
      var id = line.getAttribute("data-cart-line");
      if (t.closest("[data-cart-inc]")) { bump(id, 1); return; }
      if (t.closest("[data-cart-dec]")) { bump(id, -1); return; }
      if (t.closest("[data-cart-remove]")) { window.SHWS_CART.remove(id); return; }
    }

    // nav dropdowns (hover handles desktop; this covers touch)
    var sub = t.closest(".nav-toggle-sub");
    if (sub) {
      var panel = sub.parentNode.querySelector(".subnav");
      var openNow = sub.getAttribute("aria-expanded") === "true";
      qa(".nav-toggle-sub").forEach(function (b) { b.setAttribute("aria-expanded", "false"); });
      qa(".subnav").forEach(function (p) { p.classList.remove("open"); });
      if (!openNow && panel) { sub.setAttribute("aria-expanded", "true"); panel.classList.add("open"); }
      ev.preventDefault();
      return;
    }

    // FAQ and the product page accordion.
    // When the markup carries a checkbox the CSS already does the work, so
    // here we only keep aria-expanded truthful for screen readers.
    var fq = t.closest(".faq-q");
    if (fq) {
      var item = fq.closest(".faq-item");
      var box2 = item ? item.querySelector("input.faq-t") : null;
      if (box2) {
        setTimeout(function () { fq.setAttribute("aria-expanded", box2.checked ? "true" : "false"); }, 0);
        return;
      }
      var ans = doc.getElementById(fq.getAttribute("aria-controls")) || fq.parentNode.parentNode.querySelector(".faq-a");
      var on = fq.getAttribute("aria-expanded") === "true";
      fq.setAttribute("aria-expanded", on ? "false" : "true");
      if (ans) { ans.classList.toggle("open", !on); }
      return;
    }

    // back to top
    if (t.closest("[data-to-top]")) {
      window.scrollTo({ top: 0, behavior: "smooth" });
      return;
    }
  });

  function bump(id, by) {
    cartItems.forEach(function (i) {
      if (i.id === id) { i.qty = Math.max(1, i.qty + by); }
    });
    cartChanged();
  }

  function prefillService(value) {
    if (!value) { return; }
    var sel = q("#global-quick-quote select[name='service']");
    if (!sel) { return; }
    qa("option", sel).forEach(function (o) {
      if (o.value === value || o.textContent.trim() === value) { sel.value = o.value; }
    });
  }

  /* ---------- keyboard ---------- */
  doc.addEventListener("keydown", function (ev) {
    if (ev.key === "Escape") { closeAllDrawers(); return; }
    if (ev.key !== "Enter" && ev.key !== " " && ev.key !== "Spacebar") { return; }
    var t = ev.target;
    if (t && t.tagName === "LABEL" && t.getAttribute("role") === "button") {
      ev.preventDefault();
      t.click();
    }
  });

  /* ---------- product page buy module ---------- */
  function buyModule() {
    var form = q("[data-buy]");
    if (!form || form.__shwsBuy) { return; }
    form.__shwsBuy = true;

    function model() { return q('input[name="model"]:checked', form) || q('input[name="model"]', form); }
    function installCost() {
      var el = q('input[name="install"]', form);
      return el ? Number(el.getAttribute("data-price")) || 0 : 0;
    }
    function addons() {
      return qa('input[name="addon"]:checked', form).map(function (el) {
        return { label: el.value, price: Number(el.getAttribute("data-price")) || 0 };
      });
    }
    var qty = 1;

    function recalc() {
      var m = model();
      var unit = m ? Number(m.getAttribute("data-price")) || 0 : 0;
      var inst = installCost();
      var opts = addons().reduce(function (s, a) { return s + a.price; }, 0);
      var each = unit + inst + opts;
      set("[data-buy-product]", money(unit * qty));
      set("[data-buy-install]", money(inst * qty));
      set("[data-buy-options]", money(opts * qty));
      set("[data-buy-order]", money(each * qty));
      set("[data-buy-total]", money(each * qty));
      set("[data-qty]", String(qty));
      if (m) { set("[data-buy-name]", m.value); }
      return { unit: unit, inst: inst, opts: opts, each: each };
    }
    function set(sel, text) { var el = q(sel, form); if (el) { el.textContent = text; } }

    form.addEventListener("change", recalc);
    doc.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) { return; }
      if (t.closest("[data-qty-up]")) { qty += 1; recalc(); return; }
      if (t.closest("[data-qty-down]")) { qty = Math.max(1, qty - 1); recalc(); return; }
      if (t.closest("[data-buy-add]")) {
        var sums = recalc();
        var m = model();
        if (!m) { return; }
        var extras = addons().map(function (a) { return a.label; });
        var variant = "Installation included";
        if (extras.length) { variant += ", plus " + extras.length + " extra" + (extras.length === 1 ? "" : "s"); }
        var img = q(".pdp-shot img") || q("[data-buy-image]");
        cartAdd({
          id: (m.getAttribute("data-sku") || "item") + "|" + extras.join("+"),
          name: m.value,
          price: sums.each,
          qty: qty,
          url: location.pathname,
          variant: variant,
          image: img ? img.getAttribute("src") : ""
        });
        var added = q("[data-buy-added]");
        if (added) { added.hidden = false; }
        setDrawer("cart", true);
      }
    });
    recalc();
  }

  /* ---------- sticky header, launcher, back to top ---------- */
  function onScroll() {
    var y = window.pageYOffset || doc.documentElement.scrollTop;
    var header = q(".site-header");
    if (header) { header.classList.toggle("is-stuck", y > 8); }
    var top = q("[data-to-top]");
    if (top) { top.classList.toggle("show", y > 520); }
  }

  /* ---------- form validation ---------- */
  doc.addEventListener("invalid", function (ev) {
    var el = ev.target;
    if (!el || !el.form) { return; }
    var err = el.getAttribute("aria-describedby") ? doc.getElementById(el.getAttribute("aria-describedby")) : null;
    if (err) { err.classList.toggle("show", !el.validity.valid); }
    el.classList.toggle("bad", !el.validity.valid);
  }, true);

  doc.addEventListener("input", function (ev) {
    var el = ev.target;
    if (!el || !el.form || !el.validity) { return; }
    var err = el.getAttribute("aria-describedby") ? doc.getElementById(el.getAttribute("aria-describedby")) : null;
    if (el.validity.valid) {
      if (err) { err.classList.remove("show"); }
      el.classList.remove("bad");
    }
  });

  /* ---------- boot, and re-boot after Base44 re-renders ---------- */
  var boot = function () {
    // a page with a dark full-bleed hero gets the transparent header with white
    // type; every other page keeps the readable dark-on-light treatment.
    var header = q(".site-header");
    if (header) { header.classList.toggle("on-dark", !!q(".hero")); }

    var yr = q("#yr");
    if (yr) { yr.textContent = String(new Date().getFullYear()); }
    renderCart();
    buyModule();
    onScroll();
  };

  var pending = null, writing = false;
  function guardedBoot() {
    writing = true;
    boot();
    setTimeout(function () { writing = false; }, 0);
  }

  cartLoad();
  if (doc.readyState === "loading") { doc.addEventListener("DOMContentLoaded", guardedBoot); } else { guardedBoot(); }
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll, { passive: true });

  new MutationObserver(function () {
    if (writing) { return; }
    clearTimeout(pending);
    pending = setTimeout(guardedBoot, 160);
  }).observe(doc.body || doc.documentElement, { childList: true, subtree: true });
})();
